"""Return a version of the string escaped for inclusion in an
    RFC-822 header, by ensuring there are 8 spaces space after each newline.
    """
def _rfc822_escape(header: Any) -> object {
    lines = header.split('\n');
    header = ('\n' + (8 * ' ')).join(lines);
    return header;
}

"""Helper to extract meta values from a Celery Context"""
def tags_from_context(context: Any) -> object {
    tag_keys = (
        'compression',
        'correlation_id',
        'countdown',
        'delivery_info',
        'eta',
        'exchange',
        'expires',
        'hostname',
        'id',
        'priority',
        'queue',
        'reply_to',
        'retries',
        'routing_key',
        'serializer',
        'timelimit',
        'origin',
        'state'
    );
    tags = {};
    for key in tag_keys {
        value = context.get(key);
        if ((value is None) or (value == '')) {
            continue;
        }
        if ((key == 'timelimit') and (value in [(None, None), [None, None]])) {
            continue;
        }
        if ((key == 'retries') and (value == 0)) {
            continue;
        }
        if (key == 'origin') {
            key = 'hostname';
        }
        tag_name = 'celery.{}'.format(key);
        tags[tag_name] = value;
    }
    return tags;
}

